package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.function.Predicate;

import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.algebra.Compare;
import org.eclipse.rdf4j.sail.lmdb.ValueIds;
import org.eclipse.rdf4j.sail.lmdb.evaluation.fragment.PredicateStatus;
import org.junit.jupiter.api.Test;

/**
 * Recognition tests (fragment-fusion M1): live engine filters become fragment fast paths with exact-escape semantics,
 * and everything outside the sound subset is declined.
 */
class FragmentRecognizerTest {

	private static final long UNBOUND = -1L;
	private static final Predicate<BindingSet> NEVER = bindings -> {
		throw new AssertionError("exact fallback must not be consulted by recognition tests");
	};
	private static final NativeBindingSetValueEvaluator NEVER_VALUE = bindings -> {
		throw new AssertionError("semantic value fallback must not be consulted by recognition tests");
	};

	private static long orderedInt(long value) {
		return ValueIds.createId(ValueIds.T_ORD_INTEGER, value + ValueIds.ORDERED_BIAS);
	}

	private static LmdbNativeKernelBindings.FilterHook hook(NativeBooleanFilter filter, int... argSlots) {
		return new LmdbNativeKernelBindings.FilterHook(new MaskedFilter(filter, 0L), argSlots);
	}

	private static PredicateStatus status(LmdbNativeFragmentRecognizer.Recognized recognized, long a0) {
		return recognized.fragment().test(a0, UNBOUND, UNBOUND, recognized.binding());
	}

	@Test
	void cachedCompareAgainstOrderedConstantIsRecognized() {
		CachedCompareFilter filter = new CachedCompareFilter(4, orderedInt(18), false, Compare.CompareOp.GE, true,
				NEVER, null);
		LmdbNativeFragmentRecognizer.Recognized recognized = LmdbNativeFragmentRecognizer.recognize(hook(filter, 4));
		assertThat(recognized).isNotNull();
		assertThat(status(recognized, orderedInt(20))).isEqualTo(PredicateStatus.TRUE);
		assertThat(status(recognized, orderedInt(17))).isEqualTo(PredicateStatus.FALSE);
		assertThat(status(recognized, orderedInt(18))).isEqualTo(PredicateStatus.TRUE);
		// unbound folds to reject at the site, matching the filter's checkBound behavior
		assertThat(status(recognized, UNBOUND)).isEqualTo(PredicateStatus.ERROR);
		// dictionary literal: undecidable natively, escapes into the original filter
		assertThat(status(recognized, ValueIds.createId(ValueIds.T_LITERAL, 9))).isEqualTo(PredicateStatus.ESCAPE);
	}

	@Test
	void constantOnLeftFlipsTheComparison() {
		// FILTER(18 >= ?x) accepts x <= 18
		CachedCompareFilter filter = new CachedCompareFilter(2, orderedInt(18), true, Compare.CompareOp.GE, true,
				NEVER, null);
		LmdbNativeFragmentRecognizer.Recognized recognized = LmdbNativeFragmentRecognizer.recognize(hook(filter, 2));
		assertThat(recognized).isNotNull();
		assertThat(status(recognized, orderedInt(12))).isEqualTo(PredicateStatus.TRUE);
		assertThat(status(recognized, orderedInt(19))).isEqualTo(PredicateStatus.FALSE);
	}

	@Test
	void resourceEqualityIsRecognizedWithoutOrderedConstant() {
		long constant = ValueIds.createId(ValueIds.T_URI, 7);
		CachedCompareFilter filter = new CachedCompareFilter(0, constant, false, Compare.CompareOp.EQ, true, NEVER,
				null);
		LmdbNativeFragmentRecognizer.Recognized recognized = LmdbNativeFragmentRecognizer.recognize(hook(filter, 0));
		assertThat(recognized).isNotNull();
		assertThat(status(recognized, constant)).isEqualTo(PredicateStatus.TRUE);
		assertThat(status(recognized, ValueIds.createId(ValueIds.T_URI, 8))).isEqualTo(PredicateStatus.FALSE);
		// literal vs URI could still be value-compared by the exact tier -> escape, never a native verdict
		assertThat(status(recognized, ValueIds.createId(ValueIds.T_LITERAL, 7))).isEqualTo(PredicateStatus.ESCAPE);
	}

	@Test
	void orderComparisonAgainstNonOrderedConstantIsDeclined() {
		CachedCompareFilter filter = new CachedCompareFilter(0, ValueIds.createId(ValueIds.T_LITERAL, 3), false,
				Compare.CompareOp.LT, true, NEVER, null);
		assertThat(LmdbNativeFragmentRecognizer.recognize(hook(filter, 0))).isNull();
	}

	@Test
	void nonBoundCheckingCompareIsDeclined() {
		CachedCompareFilter filter = new CachedCompareFilter(0, orderedInt(5), false, Compare.CompareOp.GE, true,
				NEVER, null, false);
		assertThat(LmdbNativeFragmentRecognizer.recognize(hook(filter, 0))).isNull();
	}

	@Test
	void slotOutsideTheArgumentWindowIsDeclined() {
		CachedCompareFilter filter = new CachedCompareFilter(9, orderedInt(5), false, Compare.CompareOp.GE, true,
				NEVER, null);
		assertThat(LmdbNativeFragmentRecognizer.recognize(hook(filter, 4))).isNull();
	}

	@Test
	void orderedSlotCompareIsRecognizedForBothArguments() {
		OrderedSlotCompareFilter filter = new OrderedSlotCompareFilter(3, 5, Compare.CompareOp.LT, NEVER, true, true);
		LmdbNativeFragmentRecognizer.Recognized recognized = LmdbNativeFragmentRecognizer.recognize(hook(filter, 3, 5));
		assertThat(recognized).isNotNull();
		assertThat(recognized.fragment().test(orderedInt(1), orderedInt(2), UNBOUND, recognized.binding()))
				.isEqualTo(PredicateStatus.TRUE);
		assertThat(recognized.fragment().test(orderedInt(2), orderedInt(1), UNBOUND, recognized.binding()))
				.isEqualTo(PredicateStatus.FALSE);
		assertThat(recognized.fragment()
				.test(orderedInt(1), ValueIds.createId(ValueIds.T_LITERAL, 2), UNBOUND,
						recognized.binding())).isEqualTo(PredicateStatus.ESCAPE);
		// declined when a bound check is missing: unbound would not mean reject there
		OrderedSlotCompareFilter unguarded = new OrderedSlotCompareFilter(3, 5, Compare.CompareOp.LT, NEVER, false,
				true);
		assertThat(LmdbNativeFragmentRecognizer.recognize(hook(unguarded, 3, 5))).isNull();
	}

	@Test
	void booleanCombinationsComposeRecognizedChildren() {
		CachedCompareFilter lower = new CachedCompareFilter(1, orderedInt(18), false, Compare.CompareOp.GE, true,
				NEVER, null);
		CachedCompareFilter upper = new CachedCompareFilter(1, orderedInt(65), false, Compare.CompareOp.LT, true,
				NEVER, null);
		BooleanCombinationFilter range = new BooleanCombinationFilter(lower, upper, true);
		LmdbNativeFragmentRecognizer.Recognized recognized = LmdbNativeFragmentRecognizer.recognize(hook(range, 1));
		assertThat(recognized).isNotNull();
		assertThat(status(recognized, orderedInt(30))).isEqualTo(PredicateStatus.TRUE);
		assertThat(status(recognized, orderedInt(17))).isEqualTo(PredicateStatus.FALSE);
		assertThat(status(recognized, orderedInt(65))).isEqualTo(PredicateStatus.FALSE);
		assertThat(status(recognized, ValueIds.createId(ValueIds.T_LITERAL, 4))).isEqualTo(PredicateStatus.ESCAPE);
		// a combination with an unrecognized child is declined as a whole
		BooleanCombinationFilter mixed = new BooleanCombinationFilter(lower,
				new NativeValueOutcomeBooleanFilter(NEVER_VALUE, 1L << 1), true);
		assertThat(LmdbNativeFragmentRecognizer.recognize(hook(mixed, 1))).isNull();
	}

	@Test
	void negationAndSemanticValueFiltersAreDeclined() {
		CachedCompareFilter inner = new CachedCompareFilter(0, orderedInt(5), false, Compare.CompareOp.GE, true,
				NEVER, null);
		assertThat(LmdbNativeFragmentRecognizer.recognize(hook(new NegatedNativeBooleanFilter(inner), 0))).isNull();
		assertThat(LmdbNativeFragmentRecognizer
				.recognize(hook(new NativeValueOutcomeBooleanFilter(NEVER_VALUE, 1L), 0))).isNull();
	}
}
